package com.bank.access;

import java.math.BigDecimal;
import java.util.logging.*;

public class AccessModifierDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SavingsAccount rajesh = new SavingsAccount("SAV2001", new BigDecimal("1000000.00"));

        // public method: accessible everywhere
        rajesh.transfer(new BigDecimal("50000"));

        // rajesh.balance;          // private: not visible outside Account
        // rajesh.validate(...);    // protected: only same package or subclass code

        log.info(() -> "Balance via public getter = " + rajesh.getBalance());
    }
}

// ─── Would be Account.java in a real project ───
// public TOP-LEVEL class: visible everywhere.
class Account { // package-private top-level class (legal); could be public too
    private static final Logger log = Logger.getLogger("BankLog");

    private final String accountId;      // private: class-only
    private BigDecimal balance;          // private: encapsulated
    AuditHelper audit = new AuditHelper(); // package-private collaborator

    public Account(String accountId, BigDecimal balance) { // public constructor
        this.accountId = accountId;
        this.balance = balance;
    }

    public void transfer(BigDecimal amount) {      // public API surface
        validate(amount);                           // protected hook, subclass can override
        balance = balance.subtract(amount);
        audit.record(accountId, amount);            // package-private helper
        log.info(() -> accountId + " transferred " + amount + ", balance " + balance);
    }

    public BigDecimal getBalance() { return balance; } // public read access

    protected String getAccountId() { return accountId; } // protected: package + subclasses

    // protected VALIDATION HOOK: subclasses may extend this.
    protected void validate(BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("Amount must be positive");
    }
}

// ─── Would be SavingsAccount.java in a real project ───
class SavingsAccount extends Account {
    SavingsAccount(String id, BigDecimal bal) { super(id, bal); }

    // Subclass extends the PROTECTED hook; can also read protected getAccountId().
    @Override
    protected void validate(BigDecimal amount) {
        super.validate(amount);
        if (amount.compareTo(new BigDecimal("500000")) > 0)
            throw new IllegalStateException("Savings transfer limit exceeded for " + getAccountId());
    }
}

// ─── Would be AuditHelper.java in a real project ───
// package-private top-level class: only visible inside com.bank.access.
class AuditHelper {
    private static final Logger log = Logger.getLogger("BankLog");
    void record(String accountId, BigDecimal amount) { // package-private method
        log.fine(() -> "AUDIT: " + accountId + " amount " + amount);
    }
}
